. (Join-Path $PSScriptRoot 'common.ps1')
$root=Get-CloudOSRepoRoot;$templatePath=Join-Path $root 'productization\validation.json';$wrapperPath=Join-Path $PSScriptRoot 'validate-distribution-unified.ps1';$validatorPath=Join-Path $PSScriptRoot 'validate-distribution.ps1';$cmdPath=Join-Path $root 'Validar Distribuição CloudOS.cmd';$workflowPath=Join-Path $root '.github\workflows\productization-batch2-ci.yml'
foreach($path in @($templatePath,$wrapperPath,$validatorPath,$cmdPath,$workflowPath)){if(-not(Test-Path -LiteralPath $path -PathType Leaf)){throw "PHYSICAL_VALIDATOR_CONTRACT_MISSING:$path"}}
$template=Get-Content -LiteralPath $templatePath -Raw|ConvertFrom-Json;if($template.schemaVersion -ne 1 -or $template.status -ne 'not-run'){throw 'PHYSICAL_VALIDATOR_TEMPLATE_INVALID'};foreach($property in @('results','screenshots','logs','artifacts','versions','database','wsl','processes')){if(-not $template.PSObject.Properties[$property]){throw "PHYSICAL_VALIDATOR_TEMPLATE_FIELD_MISSING:$property"}};foreach($side in @('before','after')){if(-not $template.database.PSObject.Properties[$side]){throw "PHYSICAL_VALIDATOR_DATABASE_FIELD_MISSING:$side"};if(-not $template.wsl.PSObject.Properties[$side]){throw "PHYSICAL_VALIDATOR_WSL_FIELD_MISSING:$side"};if(-not $template.processes.PSObject.Properties[$side]){throw "PHYSICAL_VALIDATOR_PROCESS_FIELD_MISSING:$side"}}
$wrapper=Get-Content -LiteralPath $wrapperPath -Raw;foreach($needle in @('validation.json','screenshots','Snapshot-Db','Snapshot-Wsl','Snapshot-Processes','database=[ordered]','wsl=[ordered]','processes=[ordered]','Write-Host "explorer','Start-Process explorer.exe')){if(-not $wrapper.Contains($needle,[StringComparison]::Ordinal)){throw "PHYSICAL_VALIDATOR_CONTRACT_TEXT_MISSING:$needle"}}
$cmd=Get-Content -LiteralPath $cmdPath -Raw;if($cmd -notmatch '(?i)validate-distribution-unified\.ps1'){throw 'PHYSICAL_VALIDATOR_CMD_NOT_WIRED'}
$workflow=Get-Content -LiteralPath $workflowPath -Raw;if($workflow -match '(?im)^\s*run:\s*\.\/scripts\/productization\/validate-distribution(-unified)?\.ps1\s*$'){throw 'PHYSICAL_VALIDATOR_MUST_NOT_RUN_IN_CI'}
Write-Host 'PRODUCTIZATION_PHYSICAL_VALIDATOR_READY validationJson=true screenshots=true logs=true artifacts=true versions=true databaseBeforeAfter=true wslBeforeAfter=true processesBeforeAfter=true explorer=true gateExecuted=false'
